class Solution {    Map<Character, Set<Character>>map = new HashMap<>();    Set<Character>have = new HashSet<>();    Set<Character>need = new LinkedHashSet<>();    public String foreignDictionary(String[] words) {        for(int i=0; i<words.length; i++){            for(int j=0; j<words[i].length(); j++){                need.add(words[i].charAt(j));            }        }        for(int i=0; i<words.length-1; i++){            String w1 = words[i];            String w2 = words[i+1];            int min = Math.min(w1.length(), w2.length());            if(w1.substring(0, min).equals(w2.substring(0, min)) && w2.length() < w1.length())return new String();            for(int j=0; j<min; j++){                if(w1.charAt(j) != w2.charAt(j)){                    if(!map.containsKey(w1.charAt(j))){                        map.put(w1.charAt(j), new HashSet<>());                    }                    map.get(w1.charAt(j)).add(w2.charAt(j));                    have.add(w1.charAt(j));                    have.add(w2.charAt(j));                    break;                }            }        }        int inDeg[] = new int[126];        for(char key : map.keySet()){            System.out.print(key + " -> ");            for(char val : map.get(key)){                System.out.print(val + " ");                inDeg[val]++;            }            System.out.println();        }        StringBuilder sb = new StringBuilder();        Queue<Character>q = new LinkedList<>();        for(char i = 'a'; i <= 'z'; i++){            if(inDeg[i] == 0 && need.contains(i)){                q.offer(i);                sb.append(i);            }            if(need.contains(i))System.out.println(i + " => " + inDeg[i]);        }        while(!q.isEmpty()){            char node = q.poll();            if(map.containsKey(node)){                for(char next : map.get(node)){                    inDeg[next]--;                    if(inDeg[next] == 0){                        q.offer(next);                        sb.append(next);                    }                }            }        }        if(sb.length() != need.size())return new String();        return sb.toString();    }}